import java.util.List;
import java.util.function.Function;
import java.util.stream.Collectors;

public class LambdaProcessor {
    public List<String> processNames(List<String> rawNames, String prefix) {
        // 'prefix' is effectively final
        String localizedPrefix = prefix.trim();

        return rawNames.stream()
            .filter(name -> name != null && !name.isEmpty())
            .map(localizedPrefix::concat) // Method reference to an instance method of a particular object
            .map(String::toUpperCase)     // Method reference to an arbitrary object of a particular type
            .collect(Collectors.toList());
    }
}
